  {id:'brand', title:'Бренд-платформа', description:'Смыслы, которые нас объединяют', color:'peach', icon:2, progress:85, total:12, date:'8 ноя', status:'active'},
  {id:'research', title:'Исследование аудитории', description:'Ближе к людям, для которых создаём', color:'blue', icon:2, progress:100, total:8, date:'2 ноя', status:'done'},
];
