  {id:'2', title:'Согласовать пользовательский сценарий', project:'app', date:'Сегодня', priority:'medium', done:false},
  {id:'3', title:'Собрать референсы для айдентики', project:'brand', date:'Завтра', priority:'low', done:false},
  {id:'4', title:'Обновить компоненты дизайн-системы', project:'website', date:'Завтра', priority:'medium', done:false},
  {id:'5', title:'Провести интервью с пользователями', project:'research', date:'2 ноя', priority:'high', done:true},
  {id:'6', title:'Описать ценности бренда', project:'brand', date:'Сегодня', priority:'medium', done:true},
