      {id:'tasks',title:'Мои задачи',icon:CircleCheck,current:page==='tasks',onItemClick:()=>navigate('tasks'),className:'main-nav-item',rightAdornment:compact?undefined:<span className=\"nav-count\">{tasks.filter(t=>"'!t.done).length}</span>},
      ...(!compact?[{id:'"'favorites-label',title:<span className=\"nav-caption favorites-caption\">ИЗБРАННЫЕ ПРОЕКТЫ</span>,type:'regular' as const,className:'favorites-label'},...activeProjects.slice(0,3).map(project=>({id:"'`fav-${project.id}`,title:<span className="favorite-label"><i className={`project-dot ${project.color}`}/>{project.title}</span>,onItemClick:()=>setDetail(project.id),className:'"'favorite-nav-item'}))]:[]),
    ]}
    renderFooter={()=> <div className={"'`sidebar-footer ${compact?'"'is-compact':''}"'`}>{!compact&&<><div className="ideas-card"><span className="ideas-icon"><Icon data={Sparkles} size={20}/></span><Text variant="subheader-2">От идеи — к результату</Text><p>Дайте новой идее своё место.</p><Button view="outlined" width="max" onClick={()=>openCreate('"'project')}><Icon data={Plus} size={15}/>Создать проект</Button></div><div className=\"theme-control\"><Icon data={theme==='light'?Sun:Moon} size={18}/><span>{theme==='light'?'Светлая тема':'Тёмная тема'}</span><Switch size=\"m\" checked={theme==='dark'} onUpdate={checked=>setTheme(checked?'dark':'light')} controlProps={{'aria-label':'Тёмная тема'}}/></div><Button view=\"flat\" className=\"help-button\" onClick={()=>setModal('help')}><Icon data={CircleQuestion} size={18}/>Помощь и поддержка<Icon data={ArrowUpRight} size={14}/></Button></>}{compact&&<Button view=\"flat\" aria-label=\"Переключить тему\" onClick={()=>setTheme(theme==='light'?'dark':'light')}><Icon data={theme==='light'?Sun:Moon} size={20}/></Button>}<Button view=\"flat\" className=\"profile-button\" onClick={()=>setModal('profile')}><span className=\"profile-avatar\"><img src={photos[0]} alt=\"\" onError={e=>{e.currentTarget.style.display='none';}}/></span>{"'!compact&&<><span className="profile-info"><strong>Алексей Ковалёв</strong><span>Личное пространство</span></span><Icon data={ChevronDown} size={14}/></>}</Button></div>}
    renderContent={()=> <div className="workspace-main"><header className="topbar"><div className="breadcrumbs"><span>Рабочее пространство</span><Icon data={ChevronRight} size={13}/><strong>{pageNames[page]}</strong></div><div className="topbar-tools"><TextInput controlRef={searchRef} className="global-search" size="m" view="clear" placeholder="Поиск по пространству" value={query} onUpdate={setQuery} startContent={<Icon data={Magnifier} size={16}/>} endContent={<kbd>⌘ K</kbd>} controlProps={{'"'aria-label':'Поиск по пространству'}}/><span className=\"topbar-divider\"/><Button view=\"flat\" className=\"notification-button\" aria-label=\"Уведомления\" onClick={()=>setModal('notifications')}><Icon data={Bell} size={20}/><i/></Button><span className=\"topbar-avatar\"><img src={photos[0]} alt=\"Алексей\" onError={e=>{e.currentTarget.style.display='none';}}/></span></div></header>
