n>)}</div><Button view=\"outlined\" onClick={()=>openCreate('task')}><Icon data={Plus} size={16}/>Добавить</Button></div><Card view=\"outlined\" className=\"task-list full-task-list\"><div className=\"task-list-header\"><span>НАЗВАНИЕ ЗАДАЧИ</span><span>ПРИОРИТЕТ</span><span>СРОК</span></div>{visibleTasks.map(task=><TaskRow task={task} key={task.id}/>)}{"'!visibleTasks.length&&<Empty text="Задачи не найдены"/>}</Card></>}
