    </>:page==='"'projects'? <><div className=\"page-toolbar\"><div className=\"filter-tabs\">{[{id:'active',label:'В работе'},{id:'all',label:'Все проекты'},{id:'done',label:'Завершённые'},{id:'archived',label:'Архив'}].map(filter=><Button key={filter.id} view=\"flat\" selected={projectFilter===filter.id} className={projectFilter===filter.id?'filter-tab active':'filter-tab'} onClick={()=>setProjectFilter(filter.id)}>{filter.label}{filter.id==='active'&&<span className=\"tab-count\">{activeProjects.length}</span>}</Button>)}</div><span className=\"muted\">{visibleProjects.length} из {projects.length} проектов</span></div><div className=\"projects-grid full-projects\">{visibleProjects.map(project=><ProjectCard key={project.id} project={project}/>)}{"'!visibleProjects.length&&<Empty text={query?'"'Ничего не нашлось':'Здесь пока нет проектов'}/>}<Button className=\"new-project-tile\" view=\"outlined\" onClick={()=>openCreate('project')}><span className=\"new-project-content\"><span className=\"new-project-plus\"><Icon data={Plus} size={25}/></span><Text variant=\"subheader-2\">Новый проект</Text><span>Пусть хорошая идея станет реальностью</span></span></Button></div></>:<><div className=\"task-page-summary\"><span className=\"task-summary-icon\"><Icon data={CircleCheck} size={26}/></span><div><Text variant=\"subheader-2\">Каждая выполненная задача — маленькая победа</Text><p>Выполнено {completed} из {tasks.length} задач. Продолжайте в своём ритме.</p></div><Progress value={tasks.length?Math.round(completed/tasks.length*100):0} size=\"s\" className=\"summary-progress\"/></div><div className=\"page-toolbar\"><div className=\"filter-tabs\">{[{id:'all',label:'Все задачи'},{id:'today',label:'На сегодня'},{id:'open',label:'В работе'},{id:'done',label:'Выполненные'}].map(filter=><Button key={filter.id} view=\"flat\" selected={taskFilter===filter.id} className={taskFilter===filter.id?'filter-tab active':'filter-tab'} onClick={()=>setTaskFilter(filter.id)}>{filter.label}</Butto